import React, { useEffect, useRef, useState } from "react";
import { STATS } from "./Content";

function Counter({ to, suffix }) {
  const [val, setVal] = useState(0);
  const ref = useRef(null);
  const started = useRef(false);

  useEffect(() => {
    const obs = new IntersectionObserver(
      (entries) => {
        entries.forEach((e) => {
          if (e.isIntersecting && !started.current) {
            started.current = true;
            const duration = 1800;
            const start = performance.now();
            const tick = (now) => {
              const p = Math.min(1, (now - start) / duration);
              const eased = 1 - Math.pow(1 - p, 3);
              setVal(Math.round(to * eased));
              if (p < 1) requestAnimationFrame(tick);
            };
            requestAnimationFrame(tick);
          }
        });
      },
      { threshold: 0.3 }
    );
    if (ref.current) obs.observe(ref.current);
    return () => obs.disconnect();
  }, [to]);

  return (
    <span ref={ref} className="serif gold-shimmer" style={{ fontSize: 56 }}>
      {val.toLocaleString()}{suffix}
    </span>
  );
}

export default function About() {
  return (
    <section id="about" className="relative px-6 md:px-12 lg:px-24 py-28 md:py-36" data-testid="about-section">
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-12 items-start">
        <div className="lg:col-span-5">
          <div className="overline mb-4">The Legacy</div>
          <h2 className="serif" style={{ fontSize: "clamp(36px, 5vw, 72px)", lineHeight: 1.02, fontWeight: 300, color: "#fffff0" }}>
            A fabric house from <span style={{ color: "#d4af37", fontStyle: "italic" }}>Ludhiana,</span> adorning India's grandest celebrations.
          </h2>
        </div>
        <div className="lg:col-span-6 lg:col-start-7">
          <p className="text-base md:text-lg" style={{ color: "rgba(255,255,240,0.75)", lineHeight: 1.7, maxWidth: 580 }}>
            For over a decade, D SAJAWAT has been the quiet hand behind some of the country's most exquisite wedding venues. We source, finish and supply premium fabrics — drapes, covers, sashes, florals — to the decorators who shape memories.
          </p>
          <p className="mt-5 text-base md:text-lg" style={{ color: "rgba(255,255,240,0.6)", lineHeight: 1.7, maxWidth: 580 }}>
            From a single roll to a banquet's worth — we deliver across India, on time, in finish.
          </p>

          <div className="mt-10 grid grid-cols-2 gap-6">
            {STATS.map((s) => (
              <div key={s.label} className="glass gold-border rounded-sm p-5" data-testid={`stat-${s.label.toLowerCase().replace(/\s+/g, "-")}`}>
                <Counter to={s.value} suffix={s.suffix} />
                <div className="mt-2 overline" style={{ color: "rgba(247,231,206,0.7)" }}>
                  {s.label}
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
}
